def is_nested(string):
    open_brackets = 0
    nested = False

    for char in string:
        if char == '[':
            open_brackets += 1
            if open_brackets > 1:
                nested = True
        elif char == ']':
            if open_brackets > 0:
                open_brackets -= 1

    return nested and open_brackets == 0

